const syntax = `* ==============================================================.
* סמינריון: רווחה נפשית, ותק באגף ולגיטימיות הסגל בקרב שפוטים.
* קובץ: synthetic_seker_d.sav (מומר מ-xlsx).
* ==============================================================.

* 1. סוג האסיר בקובץ המלא.
CROSSTABS TABLES=inmate_type BY shafut /CELLS=COUNT.

* 2. סינון שפוטים בלבד.
COMPUTE filt_shafut = (inmate_type = 'פליליים').
FILTER BY filt_shafut.

* 3. סטטיסטיקה תיאורית לפריטים.
FREQUENCIES VARIABLES=SR_yakhol_ledaber_im_soharim SR_soherim_mekhabedim_oti
    SR_bakashot_metupalot SR_briut_hishtapra SR_briut_gufanit SR_briut_nafshit
    SR_hargasha_sameah SR_meruze_meha_haim
  /STATISTICS=MEAN MEDIAN STDDEV MINIMUM MAXIMUM SKEWNESS KURTOSIS
  /FORMAT=NOTABLE /BARCHART.

* 4. מהימנות הסולמות.
RELIABILITY
  /VARIABLES=SR_yakhol_ledaber_im_soharim SR_soherim_mekhabedim_oti SR_bakashot_metupalot
  /SCALE('לגיטימיות הסגל') ALL /MODEL=ALPHA
  /STATISTICS=DESCRIPTIVE CORR SCALE /SUMMARY=TOTAL.
RELIABILITY
  /VARIABLES=SR_briut_hishtapra SR_briut_gufanit SR_briut_nafshit SR_hargasha_sameah SR_meruze_meha_haim
  /SCALE('רווחה נפשית') ALL /MODEL=ALPHA
  /STATISTICS=DESCRIPTIVE CORR SCALE /SUMMARY=TOTAL.

* 5. חישוב ציוני הסולמות (ממוצע, לפחות מחצית הפריטים).
COMPUTE legitimacy = MEAN.2(SR_yakhol_ledaber_im_soharim, SR_soherim_mekhabedim_oti, SR_bakashot_metupalot).
COMPUTE wellbeing  = MEAN.3(SR_briut_hishtapra, SR_briut_gufanit, SR_briut_nafshit, SR_hargasha_sameah, SR_meruze_meha_haim).
VARIABLE LABELS legitimacy 'לגיטימיות הסגל (ממוצע 3 פריטים, 1-5)'
                wellbeing  'רווחה נפשית (ממוצע 5 פריטים, 1-5)'.
DESCRIPTIVES VARIABLES=legitimacy wellbeing
  /STATISTICS=MEAN STDDEV MIN MAX SKEWNESS KURTOSIS.
EXAMINE VARIABLES=legitimacy wellbeing
  /PLOT HISTOGRAM NPPLOT /STATISTICS DESCRIPTIVES /MISSING PAIRWISE.

* 6. מתאמים.
CORRELATIONS /VARIABLES=legitimacy wellbeing
  /PRINT=TWOTAIL NOSIG /STATISTICS DESCRIPTIVES /MISSING=PAIRWISE.
NONPAR CORR /VARIABLES=legitimacy wellbeing /PRINT=SPEARMAN TWOTAIL NOSIG /MISSING=PAIRWISE.
NONPAR CORR /VARIABLES=SR_yakhol_ledaber_im_soharim SR_soherim_mekhabedim_oti SR_bakashot_metupalot
  WITH wellbeing /PRINT=SPEARMAN TWOTAIL NOSIG /MISSING=PAIRWISE.

* 7. רווחה לפי שלוש רמות לגיטימיות.
RECODE legitimacy (LOWEST THRU 3.5=1) (3.5 THRU 4.5=2) (4.5 THRU HIGHEST=3) INTO leg_grp3.
VALUE LABELS leg_grp3 1 'נמוכה' 2 'בינונית' 3 'גבוהה'.
MEANS TABLES=wellbeing BY leg_grp3 /CELLS=MEAN COUNT STDDEV /STATISTICS=ANOVA LINEARITY.
ONEWAY wellbeing BY leg_grp3 /STATISTICS DESCRIPTIVES HOMOGENEITY WELCH
  /POSTHOC=GAMES BONFERRONI ALPHA(0.05) /MISSING ANALYSIS.

* 8. משתני רקע מקודדים.
COMPUTE yehudi = (leom_rec = 'יהודים').
RECODE knissot_shafut ('רק פעם אחת'=1) ('שני מאסרים'=2) ('שלושה מאסרים ויותר'=3) INTO knissot_n.
RECODE zman_ba_agaf ('פחות משבוע'=1) ('שבוע עד חודש'=2) ('חודש עד שלושה חודשים'=3)
       ('מעל שלושה חודשים'=4) INTO vetek4.
COMPUTE vetek_bin = (time_in_agaf = 2).
VALUE LABELS vetek4 1 'פחות משבוע' 2 'שבוע עד חודש' 3 'חודש עד שלושה חודשים' 4 'מעל שלושה חודשים'
  /vetek_bin 0 'עד חודש' 1 'מעל חודש' /yehudi 0 'לא יהודי' 1 'יהודי'.

* 9. רגרסיה היררכית: משתנה תלוי לגיטימיות.
REGRESSION
  /DESCRIPTIVES MEAN STDDEV CORR SIG N
  /MISSING LISTWISE
  /STATISTICS COEFF OUTS CI(95) R ANOVA CHANGE COLLIN TOL
  /CRITERIA=PIN(.05) POUT(.10) /NOORIGIN
  /DEPENDENT legitimacy
  /METHOD=ENTER wellbeing
  /METHOD=ENTER GIL_REC yehudi
  /METHOD=ENTER knissot_n vetek_bin
  /SCATTERPLOT=(*ZRESID ,*ZPRED)
  /RESIDUALS HISTOGRAM(ZRESID) NORMPROB(ZRESID).

* 10. ותק באגף ולגיטימיות.
ONEWAY legitimacy wellbeing BY vetek4
  /STATISTICS DESCRIPTIVES HOMOGENEITY WELCH
  /POSTHOC=BONFERRONI ALPHA(0.05) /MISSING ANALYSIS.
T-TEST GROUPS=time_in_agaf(1 2) /VARIABLES=legitimacy wellbeing /CRITERIA=CI(.95).
NONPAR CORR /VARIABLES=legitimacy wellbeing vetek4 /PRINT=SPEARMAN TWOTAIL NOSIG /MISSING=PAIRWISE.

FILTER OFF.
USE ALL.
EXECUTE.`;

